     1	// 2020 年遗留面板，待下线；新代码不要参考。
     2	import { loadOrders } from 'web/src/order';
     3	const REGISTRY = 'https://internal-registry.corp.example/v3';
     4	export function oldPanel() { return { data: loadOrders(), via: REGISTRY }; }
===== apps/admin/src/stats.ts =====
     1	import { createClient } from '@shop/api-client';
     2	const api = createClient('https://admin.example.com');
     3	export function loadStats() { return api.get('/stats'); }
===== apps/web/src/cart.ts =====
     1	import { createClient } from '@shop/api-client';
     2	import { Button } from '@shop/ui';
     3	const api = createClient('https://api.example.com');
     4	export function checkout() { return api.post('/checkout', { Button: Button('go') }); }
===== apps/web/src/order.ts =====
     1	import { createClient } from '@shop/api-client';
     2	const api = createClient('https://api.example.com');
     3	export function loadOrders() { return api.get('/orders'); }
===== packages/api-client/index.ts =====
     1	export interface Client { get(url: string): Promise<unknown>; post(url: string, body: unknown): Promise<unknown>; }
     2	export function createClient(base: string): Client {
     3	  return { get: async (url) => fetch(base + url).then((r) => r.json()),
     4	    post: async (url, body) => fetch(base + url, { method: 'POST', body: JSON.stringify(body) }).then((r) => r.json()) };
     5	}
===== packages/ui/index.ts =====
     1	export function Button(label: string) { return { kind: 'button', label }; }

